const client = $input.first().json;
const conversations = client.data?.payload || [];

// Calcular métricas baseado nas conversas do período
const now = new Date();
const from = new Date(now.getFullYear(), now.getMonth(), 1);

let leads = 0;
let contato = 0;
let agendamento = 0;
let comparecimento = 0;
let venda = 0;
let alerts = 0;
let totalRespTime = 0;
let respCount = 0;

for (const conv of conversations) {
  const created = new Date(conv.created_at);
  if (created < from) continue;

  leads++;

  // Contato: recebeu resposta da equipe
  if (conv.last_non_activity_at && conv.last_non_activity_at !== conv.created_at) {
    contato++;
  }

  // Alerta: sem resposta há mais de 24h
  if (conv.status !== 'resolved' && conv.last_non_activity_at) {
    const lastActivity = new Date(conv.last_non_activity_at);
    const hoursSince = (now - lastActivity) / (1000 * 60 * 60);
    if (hoursSince > 24) alerts++;
  }

  // Tempo de resposta
  if (conv.first_reply_created_at) {
    const replyTime = (new Date(conv.first_reply_created_at) - created) / (1000 * 60 * 60);
    totalRespTime += replyTime;
    respCount++;
  }

  // Tags para agendamento/comparecimento/venda
  const tags = (conv.tags || []).map(t => t.toLowerCase());
  if (tags.includes('agendou') || tags.includes('agendamento') || tags.includes('scheduled')) {
    agendamento++;
  }
  if (tags.includes('compareceu') || tags.includes('comparecimento') || tags.includes('attended')) {
    comparecimento++;
  }
  if (tags.includes('vendido') || tags.includes('venda') || tags.includes('sold') || tags.includes('pagou')) {
    venda++;
  }
}

const pct = (v, total) => total > 0 ? Math.round((v / total) * 100) : 0;
const respH = respCount > 0 ? Math.round((totalRespTime / respCount) * 10) / 10 : 0;

return [{
  json: {
    id: client.id,
    name: client.name,
    seg: client.seg,
    leads,
    contato,
    pct_agend: pct(agendamento, leads),
    pct_comp: pct(comparecimento, leads),
    pct_venda: pct(venda, leads),
    alerts,
    resp_h: respH
  }
}];

const items = $input.all();
const clients = items.map(i => i.json);

return [{
  json: {
    clients,
    generated_at: new Date().toISOString(),
    period: {
      from: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
      to: new Date().toISOString().split('T')[0]
    }
  }
}];

const now = new Date();
const from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
const to = now.toISOString().split('T')[0];

return [{ json: { date_from: from, date_to: to } }];
